  // RTL layout tweaks for the tools' own CSS (which assumes left-to-right)
  const style = document.createElement('style');
  style.id = 'jisr-bulk-ops-i18n-style';
  style.textContent = `
    [dir="rtl"] .jbo-table th, [dir="rtl"] .jpr-table th { text-align: right; }
    [dir="rtl"] .jbo-modal, [dir="rtl"] .jbo-hub-panel, [dir="rtl"].jbo-hub-panel, [dir="rtl"] .jpr-modal { font-family: -apple-system, "Segoe UI", Tahoma, Arial, sans-serif; }
    [dir="rtl"] input[type="number"], [dir="rtl"] input[type="date"], [dir="rtl"] input[type="month"] { direction: ltr; text-align: right; }
  `;
  (document.head || document.documentElement).appendChild(style);

  // ---------------------------------------------------------------- native dialogs
  ['alert', 'confirm', 'prompt'].forEach((fn) => {
    const orig = window[fn];
    if (typeof orig !== 'function') return;
    window[fn] = function (msg) {
      const args = Array.prototype.slice.call(arguments);
      if (lang_ === 'ar' && typeof msg === 'string') args[0] = translate_(msg) || msg;
      return orig.apply(window, args);
    };
  });

  // ---------------------------------------------------------------- follow language switches
  function recheck_() {
    const now = detectLang_();
    if (now === lang_) return;
    lang_ = now;
    applyAll_();
    listeners_.slice().forEach((fn) => { try { fn(lang_); } catch (e) { console.error('[Jisr Bulk Ops] language listener failed', e); } });
  }
