  // Shared backend (optional): a small, admin-deployed coordination service
  // (Cloudflare Worker — see the project's admin-dashboard design note) that
  // powers two things — (a) a lightweight cross-user lock so two people
  // running the same module at once get a visible warning instead of a
  // silent lost update, and (b) a live activity feed an admin can watch
  // across everyone's installs. Entirely OFF by default: until an admin
  // runs "Configure Shared Backend" from the Tampermonkey menu and sets a
  // URL, every function below resolves instantly as a no-op — nothing about
  // existing behavior changes for anyone who hasn't opted in, and a backend
  // outage/misconfiguration can never block or slow down a real bulk run
  // (every path below fails OPEN).
  // ---------------------------------------------------------------------

  function getBackendConfig_() {
    return { url: sharedGet_('backendUrl', ''), writeKey: sharedGet_('backendWriteKey', '') };
  }

  function configureBackend_() {
    const cfg = getBackendConfig_();
    const url = prompt(
      'Shared backend URL (from the deployed Cloudflare Worker) — leave blank to disable:',
      cfg.url || ''
    );
    if (url === null) return;
    const key = prompt('Shared backend write key (given to you by the admin):', cfg.writeKey || '');
    if (key === null) return;
    sharedSet_('backendUrl', url.trim().replace(/\/$/, ''));
    sharedSet_('backendWriteKey', (key || '').trim());
    toast_('Shared backend settings saved — this applies to all Jisr Bulk Ops scripts on this site, no need to repeat it per script.', 4000);
  }

  if (typeof GM_registerMenuCommand === 'function' && !unsafeWindow.__jisrBulkOpsBackendMenuRegistered) {
    unsafeWindow.__jisrBulkOpsBackendMenuRegistered = true;
    GM_registerMenuCommand('⚙️ Configure Shared Backend (Admin)', configureBackend_);
  }

  function ownerLabel_() {
    let label = sharedGet_('ownerLabel', '');
    if (!label) {
      label = (prompt('Your name — shown to teammates in cross-user warnings and in the admin activity log:', '') || '').trim() || 'unknown';
      sharedSet_('ownerLabel', label);
    }
    return label;
  }

  // A dedicated, always-re-promptable way to (re)identify this browser to
