        if (op.changes[CFG.MANAGER_FIELD] !== undefined) parts.push('Manager: ' + (op.current.managerName || '(none)') + ' → #' + op.changes[CFG.MANAGER_FIELD]);
        setStatus_(op.r, 'pending', 'would change — ' + parts.join('; '));
