    f.code = first(/employee_(code|number|no)|(^|\.)code$/i, (k) => !/gosi|nationality|country/i.test(k));
    f.name = first(/full_name(_en|_i18n)?$|(^|\.)name(_en|_i18n)?$|employee_name/i, (k) => !/nationality|country|company|issue|type|establishment/i.test(k));
    f.nationalId = first(/national|identity|id_number|iqama|document_number|(^|\.)nin$|border|passport/i, (k) => !/type|expiry|date/i.test(k));
    const gosiNum = keys.filter((k) => isNum(k) && /gosi|contribut|wage|insur/i.test(k) && !NOT_AMOUNT.test(k) && !/number|percent|rate|ratio|share|count/i.test(k));
    f.gosiWage = gosiNum.find((k) => /(wage|salary|amount)/i.test(last(k)) && /gosi/i.test(k) && !/basic|housing/i.test(last(k)))
      || gosiNum.find((k) => /(contribut\w*_?(wage|salary|amount))|(wage|salary)$/i.test(last(k)))
      || gosiNum[0] || '';
    f.comments = keys.find((k) => /(^|\.)(comments?|message|description|notes?)$/i.test(k)) || '';
    // confirmed shape: the wage only exists inside the comment sentence
    if (f.comments && flatRows.slice(0, 200).some((r) => wageFromComment_(r[f.comments]) !== null)) f.gosiWage = COMMENT_WAGE;
    const pref = (role, key) => { if (keys.includes(key)) f[role] = key; };
    pref('issueType', 'issue_type'); pref('employeeId', 'employee_id'); pref('code', 'code'); pref('name', 'name');
    pref('nationalId', 'document_number'); pref('comments', 'comments');
    f.establishment = keys.find((k) => /registration_name|establishment_name|company_name/i.test(k)) || '';
    f.gosiBasic = keys.find((k) => isNum(k) && /gosi/i.test(k) && /basic/i.test(last(k))) || '';
    f.gosiHousing = keys.find((k) => isNum(k) && /gosi/i.test(k) && /housing/i.test(last(k))) || '';
    f.jisrBasic = keys.find((k) => isNum(k) && !/gosi/i.test(k) && /basic/i.test(last(k))) || '';
    f.jisrHousing = keys.find((k) => isNum(k) && !/gosi/i.test(k) && /housing/i.test(last(k))) || '';
