      const merged = {};
      for (const key of ['id', 'name', 'name_ar', 'description']) merged[key] = !blank_(row[key]) ? row[key] : currentRow[key];
      const changed = ['name', 'name_ar', 'description'].filter((k) => String(merged[k]) !== String(currentRow[k]));
      if (!changed.length) return { isNew, skip: true, warnings: ['No change detected - skipped.'] };
