      if (!res.ok) throw new Error('Request failed (status ' + res.status + ')');
      const arr = extractArray_(res.data);
      if (!arr) throw new Error('Unexpected response shape. Top-level keys: [' + (res.data && typeof res.data === 'object' ? Object.keys(res.data).join(', ') : typeof res.data) + ']');
